import {levels,scoreDiagnostic,saveDiagnostic,readHistory,summarizeHistory,historyVersion,historyStorageFailed} from './diagnostic-progress.mjs';
export const cases=[
 {id:'pressure',label:'Presión baja',axis:'A',hint:'Compara PS / I0.4 y las dos salidas en el mismo scan.',explain:'La presión cayó de 4 a 0 bar: PS pasó a 0 y P01 retiró RUN y ambas salidas inmediatamente. No fue necesario esperar el timeout de llegada.'},
 {id:'jamA',label:'Cilindro A atascado',axis:'A',hint:'Busca si A llegó a 100 mm antes del timeout.',explain:'A quedó a mitad de carrera con PS=1 y YA=1. a1 nunca confirmó el extremo; después del límite de carrera, la red 06 retiró las salidas. Mientras siga el atasco, A tampoco podrá retornar aunque YA caiga.'},
 {id:'jamB',label:'Cilindro B atascado',axis:'B',hint:'Compara la posición de B con YB y b1 antes del fallo.',explain:'B dejó de avanzar a mitad de carrera aunque YB=1 y PS=1. b1 permaneció en 0; la red 07 disparó el timeout. Al retirar YA, A queda libre para retornar con aire; B sigue bloqueado.'},
 {id:'i1',label:'Sensor a1 desconectado',axis:'A',hint:'¿A alcanzó 100 mm mientras I0.1 seguía en 0?',explain:'A llegó físicamente al extremo, pero a1 / I0.1 siguió en 0. La red 06 generó el mismo timeout que un atasco. La posición permite distinguirlos en este simulador.'},
 {id:'i3',label:'Sensor b1 desconectado',axis:'B',hint:'¿B alcanzó 100 mm mientras I0.3 seguía en 0?',explain:'B llegó al extremo, pero b1 / I0.3 no lo confirmó. La red 07 retiró ambas salidas por timeout. El movimiento completo descarta un atasco en este reto.'}
];
export function startDiagnostic(s,random=Math.random,level='intermediate'){level=levels[level]?level:'intermediate';const config=levels[level],pool=cases.filter(c=>config.pool.includes(c.id)),item=pool[Math.min(pool.length-1,Math.floor(random()*pool.length))];s.diagnostic={level,runId:String(Date.now())+'-'+Math.random(),threshold:level==='expert'?.2+random()*.5:.35,id:item.id,injected:false,revealed:false,solved:false,hints:0,attempts:0,feedback:''};return s.diagnostic;}
export function injectDiagnostic(s){const d=s.diagnostic;if(!d||d.injected)return;const item=cases.find(c=>c.id===d.id);if((item.axis==='A'?s.x:s.y)<(d.threshold??.35))return;d.injected=true;d.time=s.time;if(d.id==='pressure')s.lowPressure=true;else if(d.id.startsWith('jam'))s[d.id]=true;else s.disabledSensors[d.id]=true;}
export function answerDiagnostic(s,answer){const d=s.diagnostic;if(!d||d.revealed)return;if(!s.fault){d.feedback='Observa primero la respuesta completa del PLC hasta la alarma.';return;}if(!cases.some(c=>c.id===answer)){d.feedback='Selecciona una hipótesis antes de comprobar.';return;}d.attempts++;if(answer===d.id){d.solved=d.revealed=true;d.feedback='Correcto. '+cases.find(c=>c.id===d.id).explain;}else d.feedback='Todavía no. Compara presión, posición alcanzada y señal de extremo antes del fallo. Puedes pedir una pista.';}
export function diagnosticHidden(s){return !!s.diagnostic&&!s.diagnostic.revealed;}
export function createDiagnosticPanel(root,{onStart,onExit,onRefresh}){const el=document.createElement('section');el.className='hmi-diagnostic';el.innerHTML=`<span class="eyebrow">MISIÓN / DIAGNÓSTICO</span><h3>Encuentra el fallo oculto</h3><p>Inicia un banco nuevo en automático. Aparecerá un único fallo sorpresa durante el avance. Observa la HMI, las tendencias y el ladder; la simulación se pausa al producirse la alarma para conservar las pruebas.</p><label>Nivel del próximo reto <select id="diagLevel"><option value="basic">Inicial</option><option value="intermediate">Intermedio</option><option value="expert">Avanzado</option></select></label><p id="diagLevelInfo"></p><p>100 puntos al acertar: −20 por cada intento incorrecto y −10 por pista. Mínimo 0. Ver solución: 0 puntos. Salir o reiniciar sin resolver registra un abandono. La puntuación no depende de la velocidad.</p><div class="hmi-actions"><button id="diagStart">Nuevo reto sorpresa</button><button id="diagHint">Pedir pista</button><button id="diagReveal">Ver solución</button><button id="diagExit">Salir y restaurar banco</button></div><p id="diagStatus" role="status"></p><p id="diagHintText"></p><label>Tu diagnóstico <select id="diagAnswer"><option value="">Selecciona una hipótesis</option>${cases.map(c=>`<option value="${c.id}">${c.label}</option>`).join('')}</select></label> <button id="diagCheck">Comprobar</button><p id="diagFeedback" role="status"></p><p>La posición es una observación del simulador, no una entrada analógica del PLC. Un timeout por sí solo no identifica un atasco ni un cable desconectado. Nuevo reto y Salir reinician el banco, el contador y las trazas.</p>`;el.insertAdjacentHTML('beforeend','<details open><summary>Mi progreso · últimos 100 retos en este navegador</summary><label>Comparar nivel <select id="diagHistoryLevel"><option value="basic">Inicial</option><option value="intermediate">Intermedio</option><option value="expert">Avanzado</option></select></label><p id="diagSummary"></p><p>Las medias incluyen retos resueltos y soluciones consultadas (0); los abandonos se cuentan por separado.</p><p id="diagStorage"></p><div class="diag-history-scroll"><table><thead><tr><th>Fecha</th><th>Resultado</th><th>Puntos</th><th>Intentos</th><th>Pistas</th></tr></thead><tbody id="diagHistory"></tbody></table></div></details>');root.prepend(el);const q=id=>el.querySelector('#'+id);let current,lastHistory='';const renderHistory=()=>{const level=q('diagHistoryLevel').value,key=historyVersion+':'+level;if(key===lastHistory)return;lastHistory=key;const rows=readHistory(),stats=summarizeHistory(rows,level);q('diagSummary').textContent=stats.total?stats.solved+' resueltos de '+stats.total+' · '+stats.abandoned+' abandonados · Mejor: '+(stats.best??'—')+' · Media últimos '+stats.recentCount+': '+(stats.recent?.toFixed(1)??'—')+(stats.previousCount?' · Media anteriores '+stats.previousCount+': '+stats.previous.toFixed(1)+' · Cambio: '+(stats.recent-stats.previous).toFixed(1):' · Completa más de 5 retos para comparar periodos.'):'Aún no hay resultados en este nivel.';q('diagStorage').textContent=historyStorageFailed()?'No se pudo guardar en el navegador; el historial está disponible solo durante esta sesión.':'Guardado local en este navegador. No se sincroniza entre dispositivos.';q('diagHistory').replaceChildren();for(const r of rows.filter(r=>r.level===level).reverse()){const row=document.createElement('tr');for(const value of [new Date(r.date).toLocaleString('es-CO'),({solved:'Resuelto',revealed:'Solución consultada',abandoned:'Abandonado'})[r.outcome],r.score+'/100',r.attempts,r.hints]){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}q('diagHistory').append(row);}};q('diagLevel').onchange=()=>{q('diagLevelInfo').textContent=levels[q('diagLevel').value].description;};q('diagLevel').onchange();q('diagHistoryLevel').onchange=renderHistory;
 q('diagStart').onclick=()=>{q('diagLevel').onchange();q('diagAnswer').value='';q('diagHistoryLevel').value=q('diagLevel').value;onStart(q('diagLevel').value);};q('diagExit').onclick=onExit;q('diagHint').onclick=()=>{if(current?.diagnostic)current.diagnostic.hints=Math.min(levels[current.diagnostic.level||'intermediate'].hints,current.diagnostic.hints+1);onRefresh();};q('diagCheck').onclick=()=>{if(current)answerDiagnostic(current,q('diagAnswer').value);onRefresh();};q('diagReveal').onclick=()=>{const d=current?.diagnostic;if(d&&current.fault){d.revealed=true;d.feedback='Solución: '+cases.find(c=>c.id===d.id).label+'. '+cases.find(c=>c.id===d.id).explain;}onRefresh();};
 renderHistory();return {update(s,disabled){current=s;const d=s.diagnostic;if(d?.revealed)saveDiagnostic(d);renderHistory();for(const id of ['diagHint','diagCheck','diagAnswer'])q(id).disabled=disabled||!d||d.revealed;q('diagHint').disabled=disabled||!d||d.revealed||d.hints>=levels[d.level||'intermediate'].hints;q('diagReveal').disabled=disabled||!d||d.revealed||!s.fault;q('diagStart').disabled=disabled;q('diagExit').disabled=disabled||!d;q('diagStatus').textContent=!d?'Banco libre. Prepara tu siguiente investigación.':d.revealed?(d.solved?'Reto resuelto':'Solución consultada')+' · '+levels[d.level||'intermediate'].label+' · '+scoreDiagnostic(d)+'/100 · Intentos: '+d.attempts+' · Pistas: '+d.hints:s.fault?'Alarma registrada. Compara las evidencias y elige una hipótesis.':'Reto '+levels[d.level||'intermediate'].label+' activo: observa el ciclo. Los mandos de inyección están ocultos.';q('diagHintText').textContent=!d||!d.hints?'':d.hints===1?'Pista 1: empieza por la presión. Después compara posición, orden de salida y sensor de extremo.':d.hints===2?'Pista 2: '+cases.find(c=>c.id===d.id).hint:'Pista 3: revisa el instante anterior a FALLO. Presión a cero, posición detenida a mitad de carrera o extremo alcanzado sin señal son evidencias distintas.';q('diagFeedback').textContent=d?.feedback||'';}};
}
